<?php $e = static fn (mixed $v): string => htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); $assigned = $role?->permissions?->pluck('id')->map(fn ($id) => (int) $id)->all() ?? []; ?>
<div class="mx-auto max-w-4xl space-y-6"><h1 class="text-2xl font-bold"><?= $e($title) ?></h1><form method="post" action="<?= $role ? '/admin/authentication/roles/' . (int) $role->id : '/admin/authentication/roles' ?>" class="space-y-5 rounded-xl border bg-white p-6 dark:border-slate-700 dark:bg-slate-800"><div class="grid gap-4 md:grid-cols-2"><label>Име<input required name="name" value="<?= $e($role?->name) ?>" class="mt-1 w-full rounded border p-2 dark:bg-slate-900"></label><label>Ключ<input required name="slug" value="<?= $e($role?->slug) ?>" class="mt-1 w-full rounded border p-2 dark:bg-slate-900"></label></div><label class="block">Описание<textarea name="description" class="mt-1 w-full rounded border p-2 dark:bg-slate-900"><?= $e($role?->description) ?></textarea></label><div><input type="hidden" name="is_active" value="0"><label><input type="checkbox" name="is_active" value="1" <?= !$role || $role->is_active ? 'checked' : '' ?>> Активна</label><label class="ml-6">Приоритет <input type="number" name="priority" value="<?= (int) ($role?->priority ?? 0) ?>" class="w-20 rounded border p-1 dark:bg-slate-900"></label></div><?php foreach ($permissions as $module => $items): ?><fieldset><legend class="mb-2 font-bold"><?= $e($module) ?></legend><div class="grid gap-2 md:grid-cols-2"><?php foreach ($items as $permission): ?><label class="rounded border p-2"><input type="checkbox" name="permissions[]" value="<?= (int) $permission->id ?>" <?= in_array((int) $permission->id, $assigned, true) ? 'checked' : '' ?>> <?= $e($permission->name) ?><code class="block text-xs text-slate-500"><?= $e($permission->slug) ?></code></label><?php endforeach; ?></div></fieldset><?php endforeach; ?><button class="rounded bg-indigo-600 px-5 py-2 text-white">Запази</button></form></div>
